pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g) public {
        vm.assume(actor != address(0));
        vm.assume(uint160(actor) > 1);
        // ensure the recorded block is never 0 (slot-empty sentinel) regardless of base block
        vm.roll(5);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // General rule: right after lockInGuess, the recorded guess block is exactly block.number + 1.
        assertEq(c.guesses(actor).block, block.number + 1);
    }
}

