pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(bytes32 h, address actor, address filler) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(filler != address(0) && filler != address(c) && filler != actor);

        // actor locks in the fuzzed guess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        // a second filler locks in so the contract holds 3 ether (payout possible)
        vm.deal(filler, 1 ether);
        vm.prank(filler);
        c.lockInGuess{value: 1 ether}(h);

        // move past the 256-block window: blockhash(target) == 0,
        // so the winning answer is keccak256(abi.encodePacked(bytes32(0)))
        vm.roll(block.number + 300);

        vm.prank(actor);
        try c.settle() { /* settle may or may not pay out */ } catch { /* payout revert is admissible */ }

        // GENERAL RULE: whenever the stored guess is the caller's own submitted hash,
        // a guess equal to the (derived) winning answer must pay out 2 ether.
        bytes32 answer = keccak256(abi.encodePacked(bytes32(0)));
        assertTrue(h != answer || address(actor).balance == 2 ether);
    }
}

