pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(c) && uint160(actor) > 9);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // advance past the locked block so settle is admissible
        vm.roll(block.number + 3);

        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        // General rule: after a successful settle, the caller's guess is cleared.
        assertTrue(ok && c.guesses(actor).block == 0);
    }
}

