pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g, uint256 target) public {
        vm.assume(actor != address(0) && actor != address(c));

        // Lock in a guess: 1 ether from the actor.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // Move to the target block so settle()'s time requirement can hold.
        if (target > block.number) {
            vm.roll(target);
        }

        // First settle attempt.
        bool ok1;
        try c.settle() { ok1 = true; } catch { ok1 = false; }

        // Second settle attempt by the same caller.
        bool ok2;
        try c.settle() { ok2 = true; } catch { ok2 = false; }

        // General rule: a caller whose first settle() succeeded may not settle again.
        assertTrue(!(ok1 && ok2));
    }
}

