pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(c));

        // Player locks in the hash of bytes32(0): in Foundry, blockhash of a
        // rolled-to empty block is 0, so this is the winning guess in the reference.
        bytes32 winningHash = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 5 ether);
        uint256 lockBlock = block.number;
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningHash);

        // Move past the target block; blockhash(targetBlock) evaluates to 0.
        vm.roll(lockBlock + 2);
        vm.prank(actor);
        c.settle();

        // Rule: a correct guess settled through settle() empties the contract
        // (the 2 ether prize is paid out). The mutant stores ~hash, never
        // matches the answer, and the contract keeps its 2 ether.
        assertTrue(address(c).balance == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amount, bytes32 h) public {
        require(address(this).balance >= amount);
        bool ok;
        (ok, ) = address(c).call{value: amount}(
            abi.encodeWithSignature("lockInGuess(bytes32)", h)
        );
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test() public {
        uint amount = 1 ether;
        require(address(this).balance >= amount);
        c.lockInGuess{value: amount}(keccak256(abi.encodePacked(uint(1))));
        assert(address(this).balance == 0);
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 g, uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(g) { reverted = false; } catch { reverted = true; }
        if (amount != 1 ether) {
            assert(reverted);
        } else {
            assert(!reverted);
        }
    }
    receive() external payable {}
}

